class MyCalendarTwo:
    def __init__(self):
        self.bookings = []
        self.overlaps = []

    def book(self, start, end):
        for s, e in self.overlaps:
            if start < e and s < end:
                return False

        for s, e in self.bookings:
            lo, hi = max(start, s), min(end, e)
            if lo < hi:
                self.overlaps.append((lo, hi))

        self.bookings.append((start, end))
        return True


def my_calendar_two(operations, args):
    calendar = MyCalendarTwo()
    results = []
    for op, arg in zip(operations, args):
        if op == 'book':
            results.append(calendar.book(arg[0], arg[1]))
    return results
